export const meta = {
  name: 'chain-AAAC',
  description: 'RUN-1 stage 2 (AAAC): fix and verify F2+F5 report.py, F3 cli --version',
  phases: [{ title: 'Fix' }, { title: 'Verify' }],
}
const VERDICT = { type: 'object', properties: {
  id: {type: 'string'}, passed: {type: 'boolean'}, why: {type: 'string'} },
  required: ['id', 'passed', 'why'] }
const M = { cheap: 'sonnet', build: 'opus', deep: 'opus' }
const tier = (t, seat) => M[t[seat]] || (() => { throw Error(`${t.id}: no ${seat} tier`) })()

const results = await pipeline(
  args,
  t => agent(`Ticket ${t.id} in the shelf repo (cwd). ${t.prompt}\n` +
             `Only touch these files: ${t.files}. Do NOT edit TICKETS.md or anything under .skillator. ` +
             `Run the full suite with: python -m pytest -q. Report what you changed, the pytest output line, ` +
             `and any unrelated problems you hit.`,
             { label: `AAAC fix:${t.id}`, phase: 'Fix', model: tier(t, 'fix') }),
  (fix, t) => agent(`Ticket ${t.id} — "${t.title}". An agent reports:\n${fix}\n` +
                    `Verify against the repo (read the code, run python -m pytest -q). Do not edit files. ` +
                    `Default to passed=false if unproven; name the check you ran in why.`,
             { label: `AAAC verify:${t.id}`, phase: 'Verify', schema: VERDICT, model: tier(t, 'verify') })
)
return results.filter(Boolean)

